INSERT INTO word (word,ipa,tier,zipf,shape,pos,definition,def_pos,etymology,etym_len,etym_band,has_signal,prior,shuffle) VALUES
('if you please',NULL,'rare',NULL,'multiword','["phrase"]','Used other than figuratively or idiomatically: see if, you, please.','phrase','The construction is unusual since the infinitive to please originally meant only “to satisfy”, not “to be satisfied”. One solution entails interpreting you as an object pronoun and please as a verb in the third-person singular subjunctive, such that if you please actually meant if it may please you. The according constructions if thee please, if him please, if them please, etc., are indeed attestable. However, if this approach is correct, the reinterpretation of the pronoun as the subject of the phrase must be very old as we also find if thou please and so on. A second hypothesis construes "if you please" as an intransitive, ergative form taken from if it pleases you which is a calque of French s''il vous plaît. Alternatively, if you please may be a bastardization of if you''d please, which is an abbreviation of if you would please be so kind, wherein please constitutes an adverb, not a verb.',903,'200plus',1,0.74,1),
('apadoline',NULL,'unattested',NULL,'plain','["noun"]','An analgesic drug.','noun','From [Term?] + -adol- (“analgesic”) + -ine.',43,'40_80',1,0.35,2),
